import{_ as s,c as t,o as a,ag as n}from"./chunks/framework.Bzez9NG9.js";const o="/space/img/settings-access.png",i="/space/img/settings-access-invite-user.png",r="/space/img/settings-access-new-access-token.png",c="/space/img/settings-access-security-roles.png",l="/space/img/settings-access-security-role-edit-create.png",d="/space/img/settings-access-secrets.png",f=JSON.parse('{"title":"Access","description":"Manage SPACE users, invitations, access tokens, security roles, secrets, and deleted access records.","frontmatter":{"title":"Access","description":"Manage SPACE users, invitations, access tokens, security roles, secrets, and deleted access records.","keywords":["SPACE access","users","invitations","access tokens","API tokens","IBMid","service account","roles","module permissions","secrets","credentials","audit trail"],"outline":"deep"},"headers":[],"relativePath":"doc/configuration/access.md","filePath":"doc/configuration/access.md"}'),p={name:"doc/configuration/access.md"};function h(u,e,g,m,v,y){return a(),t("div",null,e[0]||(e[0]=[n('<h1 id="access" tabindex="-1">Access <a class="header-anchor" href="#access" aria-label="Permalink to &quot;Access&quot;">​</a></h1><p>The <strong>Access</strong> tab in SPACE settings controls who can use SPACE and which platform capabilities are available to them.</p><p>Administrators can invite users, create access tokens for external applications and automation, manage reusable security roles, and manage centrally stored secrets.</p><p>SPACE access is managed separately from IBM Planning Analytics access. IBM Planning Analytics users, groups, and TM1 permissions continue to be managed in IBM Planning Analytics and are not replaced by SPACE roles.</p><p><img src="'+o+'" alt="Access list" data-zoomable=""></p><p>Each row shows a SPACE user or access token, its current status, and the assigned role or roles.</p><h2 id="access-record-actions" tabindex="-1">Access record actions <a class="header-anchor" href="#access-record-actions" aria-label="Permalink to &quot;Access record actions&quot;">​</a></h2><p>Select one or more records in the Access table to display the available actions. The actions depend on whether the selected record is a user or an access token.</p><p>For a selected <strong>user</strong>, you can:</p><ul><li><strong>Edit</strong> – change the user&#39;s SPACE access and assigned roles.</li><li><strong>Re-invite</strong> – resend the invitation email. This is useful when an invited user did not receive or no longer has the original invitation.</li><li><strong>Delete</strong> – remove active SPACE access by marking the user as deleted.</li></ul><p>For a selected <strong>access token</strong>, you can:</p><ul><li><strong>Edit</strong> – change the token&#39;s SPACE access and assigned roles.</li><li><strong>Regenerate token</strong> – rotate the credential by generating a new token value. The previous token value becomes invalid and any application or automation using it must be updated.</li><li><strong>Delete</strong> – remove active access by marking the token as deleted.</li></ul><p>Multiple users or tokens can be selected and deleted in one operation.</p><h2 id="inviting-users" tabindex="-1">Inviting users <a class="header-anchor" href="#inviting-users" aria-label="Permalink to &quot;Inviting users&quot;">​</a></h2><p>Click <strong>Invite user</strong> to add a SPACE user.</p><p><img src="'+i+'" alt="Invite user modal" data-zoomable=""></p><p>Provide the user email and assign either admin access or one or more SPACE security roles.</p><p>Depending on the authentication configuration, the invitation identifies the user who will sign in to SPACE and the Planning Analytics environment associated with the invitation.</p><p>An optional expiry date can be used when access should be available only for a limited period.</p><h2 id="access-tokens" tabindex="-1">Access tokens <a class="header-anchor" href="#access-tokens" aria-label="Permalink to &quot;Access tokens&quot;">​</a></h2><p>Click <strong>New token</strong> to create an access token for an external application, integration, or automated process that needs to call SPACE without an interactive user session.</p><p><img src="'+r+'" alt="Create access token modal" data-zoomable=""></p><p>Specify a descriptive token name, assign the required role or admin access, and optionally set an expiry date.</p><p>After creation, copy the token and store it securely. SPACE does not display the token value again.</p><p>Access tokens can be used by applications that call the SPACE API. For example, an IBM Planning Analytics TurboIntegrator process can use a SPACE token to call SPACE and trigger supported operations such as running a Python script.</p><p>Assign only the roles required by the integration and use an expiry date when long-lived access is not necessary.</p><h2 id="security-roles" tabindex="-1">Security roles <a class="header-anchor" href="#security-roles" aria-label="Permalink to &quot;Security roles&quot;">​</a></h2><p>Select <strong>Manage roles</strong> from the Access actions menu to configure reusable SPACE security roles.</p><p><img src="'+c+'" alt="Security roles list" data-zoomable=""></p><p>Roles group SPACE permissions so the same access definition can be assigned to multiple users or tokens.</p><p>Use <strong>New role</strong> to create a role and select the platform capabilities it grants. Editing a role updates the access of users and tokens that reference that role.</p><p><img src="'+l+'" alt="Role editor modal" data-zoomable=""></p><p>Use descriptive role names, such as <code>Audit Log Viewer</code>, <code>AI Assistant</code>, or <code>QA testers</code>, so administrators can easily understand their intended purpose.</p><p>SPACE roles control access to platform functionality. Connection-specific capabilities are configured separately for each connection under <a href="./connections/">Connections</a>.</p><h2 id="secrets" tabindex="-1">Secrets <a class="header-anchor" href="#secrets" aria-label="Permalink to &quot;Secrets&quot;">​</a></h2><p>Select <strong>Manage secrets</strong> from the Access actions menu to manage credentials and other sensitive values that SPACE can make available to supported workflows.</p><p><img src="'+d+'" alt="Secrets management" data-zoomable=""></p><p>Secrets are centrally managed by SPACE administrators and can contain fields such as usernames, passwords, API keys, or other credentials required by Python scripts and integrations.</p><p>Python code can retrieve approved secrets at runtime through the <a href="./../python/secrets-and-connections.html">SPACE Python SDK</a>, allowing credentials to remain outside notebooks, scripts, and Git repositories.</p><p>Secret values should be treated as sensitive configuration. Administrators can manage the stored secret definitions from SPACE settings, while Python workflows access them only when required.</p><h2 id="deleted-users-and-tokens" tabindex="-1">Deleted users and tokens <a class="header-anchor" href="#deleted-users-and-tokens" aria-label="Permalink to &quot;Deleted users and tokens&quot;">​</a></h2><p>SPACE keeps historical identity records so activity can remain attributable even after access is removed.</p><p>Users and access tokens are not physically removed when deleted. They are marked as deleted and no longer provide active access. Use <strong>Show deleted</strong> to include these records in the Access list.</p><p>Keeping the original record allows previous journal entries, jobs, logs, and other recorded activity to remain associated with the user or token that performed the action. This preserves a continuous audit history even after access has been removed.</p><p>If a previously deleted user is invited again using the same email address, SPACE restores the existing user record instead of creating a new one. The same identity is therefore reused and its previous activity remains associated with that user.</p><p>Access tokens follow the same principle. If a new token is created using the same name as a previously deleted token, SPACE restores the existing token record so its historical activity remains associated with the same integration. A <strong>new token value is always generated</strong>; previously issued token values remain invalid.</p><p>This behavior preserves historical traceability while ensuring that deleted credentials cannot become valid again.</p><h2 id="connection-access" tabindex="-1">Connection access <a class="header-anchor" href="#connection-access" aria-label="Permalink to &quot;Connection access&quot;">​</a></h2><p>SPACE roles define platform-level access, while each Planning Analytics connection can grant a different set of capabilities to those roles.</p><p>For example, a role can have read-only access to a production connection while receiving model-development capabilities on a development connection.</p><p>Configure these mappings from the <strong>Access</strong> action on the selected connection. See <a href="./connections/#access">Connections → Connection access</a> for the available connection capabilities.</p><p>Native IBM Planning Analytics authentication and TM1 security continue to apply when SPACE accesses the underlying Planning Analytics environment.</p>',52)]))}const b=s(p,[["render",h]]);export{f as __pageData,b as default};
